'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const C = input[2];
const values = input.slice(3);

if (K * C === N) {
  console.log(0);
} else if (C === 1) {
  values.sort((a, b) => a - b);
  let covered = 0;
  for (let i = 0; i < K; i++) covered += values[i];
  console.log(values.reduce((sum, value) => sum + value, 0) - covered);
} else {
  const prefix = new Array(N + 1).fill(0);
  for (let i = 0; i < N; i++) prefix[i + 1] = prefix[i] + values[i];

  let previous = new Array(N + 1).fill(0);
  let current = new Array(N + 1);

  for (let count = 1; count <= K; count++) {
    const first = count * C;
    current[first - 1] = Infinity;

    for (let end = first; end <= N; end++) {
      const intervalSum = prefix[end] - prefix[end - C];
      current[end] = Math.min(
        current[end - 1],
        previous[end - C] + intervalSum
      );
    }

    [previous, current] = [current, previous];
  }

  console.log(prefix[N] - previous[N]);
}
